steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { workflowStates(includeArchived: false, teamId: \"t-web\") { nodes { id name } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { workflowStates(includeArchived: false) { nodes { id name team { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { workflowStateArchive(id: \"t-web-st-blocked\") { success } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { workflowState: { id: { eq: \"t-web-st-blocked\" } } }) { nodes { id identifier name state { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { state: { id: { eq: \"t-web-st-blocked\" } } }) { nodes { id identifier title state { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-web-2\", input: { stateId: \"t-web-st-1\" }) { success } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { workflowStateArchive(id: \"t-web-st-blocked\") { success } }"
  }'
